// One picture of the plan for both agents: projects -> their weekly items -> daily tasks, read from Notion just now
const txt = (a) => (a || []).map((t) => t.plain_text).join('');
const rt = (p) => (p ? txt(p.rich_text || p.title) : '');
const sel = (p) => (p && p.select ? p.select.name : null);
const num = (p) => (p && typeof p.number === 'number' ? p.number : null);
const dt = (p) => (p && p.date && p.date.start ? p.date.start.slice(0, 10) : null);
const rel = (p) => (p && Array.isArray(p.relation) ? p.relation.map((r) => r.id) : []);
const fml = (p) => (p && p.formula ? (p.formula.string ?? p.formula.boolean ?? p.formula.number ?? null) : null);
const day = (s) => String(s || '').slice(0, 10);
const read = (n) => {
  try {
    const all = $(n).all().map((i) => i.json);
    return { failed: all.some((j) => j && j.error), pages: all.filter((p) => p && p.properties) };
  } catch (e) { return { failed: true, pages: [] }; }
};
const P = read('Fetch Projects'), G = read('Fetch Weekly Plan'), T = read('Fetch Tasks');
const read_failed = [['Fetch Projects', P], ['Fetch Weekly Plan', G], ['Fetch Tasks', T]].filter((x) => x[1].failed).map((x) => x[0]);

const projects = P.pages.map((pg) => {
  const p = pg.properties;
  return {
    id: pg.id, name: rt(p['Project Name']), status: sel(p['Status']), rank: num(p['Rank']), edited: day(pg.last_edited_time),
    why: rt(p['Why']), goal: rt(p['Goal']), oos: rt(p['Out of Scope']), metric: rt(p['Metric']),
    baseline: num(p['Baseline']), target: num(p['Target']), who: rt(p['Who']), chance: num(p['Chance %']),
    prediction: num(p['Prediction']), low: num(p['Range Low']), high: num(p['Range High']),
    deadline: dt(p['Deadline']), checkpoints: rt(p['Checkpoints']), blockers: rt(p['Blockers']),
    assumptions: rt(p['Assumptions']), iteration: num(p['Iteration']), parked: rt(p['Parked Reason']),
    notes: rt(p['Notes']), idea: rel(p['Source Idea']), smartBox: fml(p['SMART Complete'])
  };
});
const statusOrder = { Active: 0, 'On Hold': 1, Shaping: 2, Parked: 3 };
projects.sort((a, b) => (statusOrder[a.status] ?? 9) - (statusOrder[b.status] ?? 9) || (a.rank ?? 99) - (b.rank ?? 99));
const projById = Object.fromEntries(projects.map((p) => [p.id, p]));

const allGoals = G.pages.map((pg) => {
  const p = pg.properties;
  return {
    id: pg.id, name: rt(p['Task Name']), type: sel(p['Type']), status: sel(p['Status']), priority: sel(p['Priority']),
    complexity: sel(p['Complexity']), estimate: sel(p['Time Estimate']), due: dt(p['Due Date']), timing: fml(p['Timing']),
    moved: num(p['Times Moved']) || 0, project: rel(p['Project'])[0] || null, link_status: sel(p['Link Status']),
    done_when: rt(p['Done When']), confidence: num(p['Confidence %']), result: sel(p['Result']),
    daily_tasks: rel(p['Daily Tasks']), edited: day(pg.last_edited_time)
  };
}).sort((a, b) => String(a.due || '9999').localeCompare(String(b.due || '9999')));
// Goals of past weeks that already have a Result: only for the Coach's calibration, never shown in the tree
const weekMon = $now.startOf('week').toISODate();
const scored_goals = allGoals.filter((g) => g.result && g.due && g.due < weekMon);
// Last week's goals not scored yet: for a review held late (Monday to Friday); closed ones are not shown in the tree
const lastMon = $now.startOf('week').minus({ weeks: 1 }).toISODate();
const last_week_goals = allGoals.filter((g) => !g.result && g.due && g.due >= lastMon && g.due < weekMon);
const isClosed = (g) => g.status === 'Done' || g.status === 'Cancelled';
const goals = allGoals.filter((g) => !scored_goals.includes(g) && !(last_week_goals.includes(g) && isClosed(g)));

const tasks = T.pages.map((pg) => {
  const p = pg.properties;
  return {
    id: pg.id, name: rt(p['Task Name']), status: sel(p['Status']), priority: sel(p['Priority']), complexity: sel(p['Complexity']),
    due: dt(p['Due Date']), timing: fml(p['Timing']), moved: num(p['Times Moved']) || 0,
    weekly_item: rel(p['Weekly Item'])[0] || null, subtasks: rel(p['Subtasks']).length, edited: day(pg.last_edited_time)
  };
});

// Text block, identical for both agents
const wd = (d) => (d ? DateTime.fromISO(d).setLocale('en').toFormat('ccc yyyy-LL-dd') : 'no date');
const counts = (g) => {
  const ts = tasks.filter((t) => t.weekly_item === g.id);
  if (!ts.length) return '';
  const d = ts.filter((t) => t.status === 'Done').length, c = ts.filter((t) => t.status === 'Cancelled').length;
  return ' · daily tasks: ' + d + ' done, ' + (ts.length - d - c) + ' open, ' + c + ' cancelled';
};
const goalLine = (g) => '  - ' + (g.type || 'Item') + ' "' + g.name + '" [id ' + g.id + '] · due ' + wd(g.due) + ' · ' + (g.status || '-') +
  (g.priority ? ' · ' + g.priority : '') + (g.complexity ? ' · ' + g.complexity : '') + (g.timing ? ' · ' + g.timing : '') + (g.done_when ? ' · done when: ' + g.done_when.replace(/\s+/g, ' ') : '') + (g.confidence !== null ? ' · confidence ' + g.confidence + '%' : '') + (g.result ? ' · result: ' + g.result : '') + (g.moved ? ' · due date moved ' + g.moved + ' times' : '') + counts(g) + ' · last edited ' + g.edited;
const out = ['PLAN TREE (read from Notion at ' + $now.toFormat('yyyy-LL-dd HH:mm') + '; a project holds the outcome, its weekly items hold how it is done; statuses and counts are only these)'];
if (read_failed.length) out.push('NOTION READ FAILED: ' + read_failed.join(', ') + '. The tree may be incomplete.');
for (const p of projects) {
  out.push('- Project "' + p.name + '" [id ' + p.id + '] · ' + (p.status || '-') + (p.rank !== null ? ' · Rank ' + p.rank : '') + (p.deadline ? ' · deadline ' + wd(p.deadline) : '') + ' · page last edited ' + p.edited);
  const gs = goals.filter((g) => g.project === p.id);
  if (!gs.length) out.push('  (no weekly items from this week on)');
  for (const g of gs) out.push(goalLine(g));
}
const closed = goals.filter((g) => g.project && !projById[g.project]);
if (closed.length) { out.push('- Linked to a project that is Done or Killed:'); for (const g of closed) out.push(goalLine(g)); }
const noProj = goals.filter((g) => !g.project);
for (const [label, test] of [['Personal (no project)', (g) => g.link_status === 'Personal'], ['Waiting for a project', (g) => g.link_status === 'Waiting for project'], ['NOT LINKED (needs a project or Personal)', (g) => !g.link_status]]) {
  const gs = noProj.filter(test);
  if (gs.length) { out.push('- ' + label + ':'); for (const g of gs) out.push(goalLine(g)); }
}
if (!goals.length) out.push('- No weekly items from this week on.');

// Renames and status changes since this agent last read the tree, found by Notion page id (an id never changes, a name can).
// The agent writes the note into its chat memory, so old messages that use an old name are understood.
const caller = (() => { try { return $('Receive Tree Call').first().json || {}; } catch (e) { return {}; } })();
const chatId = String(caller.chat_id || '');
const who = String(caller.agent_name || 'unknown') + ':' + chatId;
const isTest = /^ZZTEST/.test(chatId); // test chats are compared but never stored
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
// No seed in the demo: names are tracked from the first call
const SEED = {};
const known = store.seen[who];
const before = known || SEED;
const nowSeen = {};
for (const p of projects) nowSeen[p.id] = { kind: 'project', name: p.name, status: p.status };
for (const g of goals) nowSeen[g.id] = { kind: g.type === 'Task' ? 'weekly task' : 'weekly goal', name: g.name, status: g.status };
const changes = [];
for (const [id, cur] of Object.entries(nowSeen)) {
  const old = before[id];
  if (!old) continue;
  if (old.name && old.name !== cur.name) changes.push('the ' + cur.kind + ' "' + old.name + '" [id ' + id + '] is now called "' + cur.name + '". It is the same ' + cur.kind + ': earlier messages that use the old name mean this one');
  if (cur.kind === 'project' && old.status && old.status !== cur.status) changes.push('the project "' + cur.name + '" [id ' + id + '] changed status from ' + old.status + ' to ' + cur.status);
}
if (known && !read_failed.length) for (const [id, old] of Object.entries(known)) if (old.kind === 'project' && !nowSeen[id]) changes.push('the project "' + old.name + '" [id ' + id + '] is no longer open (Done or Killed in Notion): do not treat it as active');
if (!isTest && !read_failed.length) store.seen[who] = nowSeen;
const memory_note = changes.length ? 'MEMORY UPDATE (' + $now.toFormat('yyyy-LL-dd HH:mm') + ', written by the workflow from Notion page ids, not by you): ' + changes.join('; ') + '. Use only the new names from now on.' : '';

return [{ json: { projects, goals, scored_goals, last_week_goals, tasks, read_failed, text: out.join('\n'), memory_note } }];
